   # from i,j pair, remove having lesser ci
   ired=c(i[ci[i] <= ci[j]], j[ci[j] <= ci[i]])
   #browser()
   if (length(ired)) {
      cat("Following ", length(ired), " inequalities are redundant and removed:
	", paste0(nm_i[ired], collapse="
	"), "
", sep="", file=fclog)
